using System;
using System.IO;
using System.Runtime.InteropServices;
using GoogleNasInstaller;
class SuiteInstallerTests {
 [STAThread]static int Main(string[] args){try{if(!SetupEngine.SuitePackage)throw new Exception("Suite define missing");string root=Path.GetFullPath(args[0]),target=Path.Combine(root,"target"),menu=Path.Combine(root,"menu");Directory.CreateDirectory(target);Directory.CreateDirectory(menu);File.WriteAllText(Path.Combine(target,"CyanNas.exe"),"fixture");File.WriteAllText(Path.Combine(target,"Uninstall.exe"),"fixture");File.WriteAllText(Path.Combine(menu,"CYAN NAS SERVER.lnk"),"old fixture");File.WriteAllText(Path.Combine(menu,"CYAN NAS CLIENT.lnk"),"old fixture");var error=SetupEngine.CreateShortcuts(menu,target);if(error!=null)throw new Exception(error);string link=Path.Combine(menu,"CYAN NAS.lnk");if(!File.Exists(link)||File.Exists(Path.Combine(menu,"CYAN NAS SERVER.lnk"))||File.Exists(Path.Combine(menu,"CYAN NAS CLIENT.lnk")))throw new Exception("Installer must expose one shortcut and remove old role shortcuts");object shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell")),shortcut=null;try{dynamic s=shell;shortcut=s.CreateShortcut(link);dynamic l=shortcut;if(!string.Equals((string)l.TargetPath,Path.Combine(target,"CyanNas.exe"),StringComparison.OrdinalIgnoreCase))throw new Exception("Wrong unified target");}finally{if(shortcut!=null)Marshal.FinalReleaseComObject(shortcut);Marshal.FinalReleaseComObject(shell);}Console.WriteLine("Unified installer: one shortcut, correct target and old shortcut cleanup passed.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}